<?php
namespace App\Console\Commands\Developer;use App\Enums\TenantStatus;use App\Models\Tenant;use Illuminate\Console\Command;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Http;use Throwable;
class DeliverWebhooksCommand extends Command{protected $signature='webhooks:deliver';protected $description='Deliver queued tenant webhooks with HMAC signatures and retry backoff';public function handle():int{foreach(Tenant::where('status',TenantStatus::Active)->get() as $tenant){try{tenancy()->initialize($tenant);$this->tenant();}catch(Throwable $e){report($e);}finally{if(tenancy()->initialized)tenancy()->end();}}return self::SUCCESS;}private function tenant():void{DB::table('outbound_webhook_deliveries')->whereIn('status',['pending','retrying'])->where('next_attempt_at','<=',now())->orderBy('id')->limit(100)->get()->each(function($delivery):void{$hook=DB::table('outbound_webhooks')->where('id',$delivery->outbound_webhook_id)->where('active',true)->first();if(!$hook)return;$host=parse_url($hook->url,PHP_URL_HOST);if(parse_url($hook->url,PHP_URL_SCHEME)!=='https'||in_array(strtolower((string)$host),['localhost','127.0.0.1','::1'],true)){DB::table('outbound_webhook_deliveries')->where('id',$delivery->id)->update(['status'=>'failed','response_excerpt'=>'Only public HTTPS endpoints are allowed.','updated_at'=>now()]);return;}$payload=$delivery->payload;$signature=hash_hmac('sha256',$payload,Crypt::decryptString($hook->secret_encrypted));try{$response=Http::timeout(10)->withHeaders(['X-PromptBot-Event'=>$delivery->event,'X-PromptBot-Delivery'=>$delivery->event_id,'X-PromptBot-Signature'=>'sha256='.$signature])->withBody($payload,'application/json')->post($hook->url);$attempts=$delivery->attempts+1;$success=$response->successful();DB::table('outbound_webhook_deliveries')->where('id',$delivery->id)->update(['attempts'=>$attempts,'status'=>$success?'delivered':($attempts>=8?'failed':'retrying'),'response_code'=>$response->status(),'response_excerpt'=>substr($response->body(),0,1000),'delivered_at'=>$success?now():null,'next_attempt_at'=>$success?null:now()->addMinutes(min(1440,2**$attempts)),'updated_at'=>now()]);}catch(Throwable $e){$attempts=$delivery->attempts+1;DB::table('outbound_webhook_deliveries')->where('id',$delivery->id)->update(['attempts'=>$attempts,'status'=>$attempts>=8?'failed':'retrying','response_excerpt'=>substr($e->getMessage(),0,1000),'next_attempt_at'=>now()->addMinutes(min(1440,2**$attempts)),'updated_at'=>now()]);}});}}
